import pandas as pd
import numpy as np

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    invoices = inputs["invoices"].copy()

    # Initialize a list to collect failure codes for each row
    failure_codes = [[] for _ in range(len(invoices))]

    # R1: amount IS NULL OR amount < 0 -> 'AMT_BAD'
    r1_fail = invoices["amount"].isna() | (invoices["amount"] < 0)
    for i in range(len(invoices)):
        if r1_fail.iloc[i]:
            failure_codes[i].append("AMT_BAD")

    # R2: tax IS NULL OR tax < 0 -> 'TAX_BAD'
    r2_fail = invoices["tax"].isna() | (invoices["tax"] < 0)
    for i in range(len(invoices)):
        if r2_fail.iloc[i]:
            failure_codes[i].append("TAX_BAD")

    # R3: tax > amount * 0.5 -> 'TAX_EXCESS'
    # NULL-safe: only check if both amount and tax are not NULL
    r3_fail = (~invoices["amount"].isna()) & (~invoices["tax"].isna()) & (invoices["tax"] > invoices["amount"] * 0.5)
    for i in range(len(invoices)):
        if r3_fail.iloc[i]:
            failure_codes[i].append("TAX_EXCESS")

    # R4: due_date IS NULL -> 'DUE_NULL'
    r4_fail = invoices["due_date"].isna()
    for i in range(len(invoices)):
        if r4_fail.iloc[i]:
            failure_codes[i].append("DUE_NULL")

    # R5: customer_ref IS NULL OR TRIM(customer_ref) = '' -> 'REF_EMPTY'
    r5_fail = invoices["customer_ref"].isna() | (invoices["customer_ref"].str.strip() == "")
    for i in range(len(invoices)):
        if r5_fail.iloc[i]:
            failure_codes[i].append("REF_EMPTY")

    # Create reason_codes column with pipe-delimited codes
    invoices["reason_codes"] = ["" if len(codes) == 0 else "|".join(codes) for codes in failure_codes]

    # Split into clean and rejects
    has_failures = invoices["reason_codes"] != ""

    invoices_clean = invoices[~has_failures].drop(columns=["reason_codes"]).reset_index(drop=True)
    invoices_rejects = invoices[has_failures][["invoice_id", "amount", "tax", "due_date", "customer_ref", "reason_codes"]].reset_index(drop=True)

    return {
        "invoices_clean": invoices_clean,
        "invoices_rejects": invoices_rejects
    }
